            return None;
        }
    };

    match from_tokenstream_spanned::<EndpointMetadata>(
        l.delimiter.span(),
        &l.tokens,
    ) {
        Ok(m) => m.validate(name_str, attr, MacroKind::Trait, errors),
        Err(error) => {
            errors.push(Error::new(
                error.span(),
                format!(
                    "endpoint `{name_str}` has invalid attributes: {error}"
                ),
            ));
            return None;
        }
    }
